// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract InvMutTest is Test {
    PuttyV2 c;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
    }

    function testFuzz_property(uint256 nonce, address recipient) public {
        FakeToken token = new FakeToken();
        Maker maker = new Maker();
        vm.assume(recipient != address(0));
        vm.assume(recipient != address(maker));

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        PuttyV2.ERC20Asset[] memory erc20Assets = new PuttyV2.ERC20Asset[](0);
        PuttyV2.ERC721Asset[] memory erc721Assets = new PuttyV2.ERC721Asset[](0);

        PuttyV2.Order memory order = PuttyV2.Order({
            maker: address(maker),
            isCall: true,
            isLong: true,
            baseAsset: address(token),
            strike: 0,
            premium: 0,
            duration: 1,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        uint256 tokenId = uint256(orderHash);

        uint256[] memory noFloorIds = new uint256[](0);
        bytes memory sig = new bytes(65);

        c.fillOrder(order, sig, noFloorIds);

        maker.doTransferFrom(c, recipient, tokenId);

        assertTrue(c.ownerOf(tokenId) == recipient);
    }
}

contract FakeToken {
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }
}

contract Maker {
    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return 0x1626ba7e;
    }

    function doTransferFrom(PuttyV2 c, address to, uint256 id) external {
        c.transferFrom(address(this), to, id);
    }
}
